pm.test("US05 CA-03: el filtro devuelve solo productos del estado pedido", () => {
    pm.response.to.have.status(200);
    const items = pm.response.json().items;
    pm.expect(items.length, "debe haber al menos un producto").to.be.above(0);
    items.forEach(p => {
        pm.expect(p.status).to.eql("DISCONTINUED");
        pm.expect(p.category).to.eql("ELECTRONICS");
    });
});

